test('mobile result pagination remains reachable inside the embedded result frame', async ({ page }) => {
	await page.setViewportSize({ width: 390, height: 900 });
	await openPage(page, `repositories/${REPOSITORY_ID}/query`);
	await page.evaluate(() => window.RDF4JWorkbenchTheme.setPreference('dark'));
	const values = Array.from({ length: 125 }, (_, index) => `(<urn:page:${index}> "${index}")`).join(' ');
	const query = `SELECT ?s ?label WHERE { VALUES (?s ?label) { ${values} } }`;
	await page.locator('.CodeMirror').first().evaluate((editor, queryText) => editor.CodeMirror.setValue(queryText), query);
	await page.locator('#exec').click();
	const frame = page.frameLocator('#query-results-frame');
	await expect(frame.locator('table.data tbody tr')).toHaveCount(100);
	await expect(page.locator('#query-results-loading')).toBeHidden();
	await expect(frame.locator('#nextX')).toBeVisible();

	const beforeScroll = await page.locator('#query-results-frame').evaluate(frameElement => {
		const document = frameElement.contentDocument;
		const button = document.getElementById('nextX');
		const buttonBounds = button.getBoundingClientRect();
		return {
			frameHeight: frameElement.getBoundingClientRect().height,
			viewportHeight: document.documentElement.clientHeight,
			documentHeight: Math.max(document.documentElement.scrollHeight, document.body.scrollHeight),
			buttonTop: buttonBounds.top,
			buttonBottom: buttonBounds.bottom,
			scrollY: document.defaultView.scrollY
		};
	});
	console.log(`RESULT_FRAME_PAGINATION_BEFORE_SCROLL ${JSON.stringify(beforeScroll)}`);
	expect(beforeScroll.documentHeight).toBeGreaterThan(beforeScroll.viewportHeight);

	await frame.locator('#nextX').scrollIntoViewIfNeeded();
	const afterScroll = await page.locator('#query-results-frame').evaluate(frameElement => {
		const document = frameElement.contentDocument;
		const buttonBounds = document.getElementById('nextX').getBoundingClientRect();
		return {
			viewportHeight: document.documentElement.clientHeight,
			buttonTop: buttonBounds.top,
			buttonBottom: buttonBounds.bottom,
			scrollY: document.defaultView.scrollY
		};
	});
	console.log(`RESULT_FRAME_PAGINATION_AFTER_SCROLL ${JSON.stringify(afterScroll)}`);
	expect(afterScroll.scrollY).toBeGreaterThan(0);
	expect(afterScroll.buttonTop).toBeGreaterThanOrEqual(0);
	expect(afterScroll.buttonBottom).toBeLessThanOrEqual(afterScroll.viewportHeight);
	if (VISUAL_ARTIFACT_DIRECTORY) {
		const directory = path.join(VISUAL_ARTIFACT_DIRECTORY, 'final', 'dark-expanded');
		fs.mkdirSync(directory, { recursive: true });
		await page.locator('#query-results-frame').scrollIntoViewIfNeeded();
		await page.screenshot({ path: path.join(directory,
			'query-result-pagination-reachable-390-dark.png'), fullPage: false });
	}
});

test('query result table headers stay visible while scrolling rows on desktop and mobile', async ({ page }) => {
	const pageErrors = [];
	page.on('pageerror', error => pageErrors.push(error.message));
	await page.setViewportSize({ width: 1440, height: 900 });
	await openPage(page, `repositories/${REPOSITORY_ID}/query`);
	const wideValues = Array.from({ length: 5 }, (_, index) =>
		`"wide-value-${index}-${'abcdefghij'.repeat(6)}"`).join(' ');
	const query = `SELECT ?subject ?predicate ?object WHERE { VALUES ?subject { ${wideValues} } `
		+ 'VALUES ?predicate { 1 2 3 4 5 } VALUES ?object { 1 2 3 4 5 } }';
	await page.locator('.CodeMirror').first().evaluate((editor, queryText) => editor.CodeMirror.setValue(queryText), query);
	await page.locator('#exec').click();
	const results = page.locator('#query-results');
	await expect(results.locator('.query-result-table-wrap')).toBeVisible();
	await expect(results.locator('.query-result-table-wrap table.data tbody tr').first()).toBeVisible();
	const pagePaging = results.locator('nav[aria-label="Query result paging"]');
	await expect(pagePaging.locator('.query-result-navigation__label')).toHaveText('Page 1 of 2');
	const optionsToggle = results.locator('.query-result-options-toggle');
	const optionsPanel = results.locator('.query-result-disclosure-panels .query-disclosure__panel').nth(1);
	await optionsToggle.click();
	await expect(optionsPanel).toBeVisible();
	await results.locator('select[name="result-layout"]').selectOption('table');
	await expect(results.locator('.query-result-layout')).toHaveAttribute('data-effective-layout', 'table');
	await optionsToggle.click();

	const screenshotPrefix = process.env.WORKBENCH_STICKY_HEADER_SCREENSHOT_PREFIX
		|| '/private/tmp/workbench-query-sticky-header';
	for (const viewport of [{ width: 1440, height: 900 }, { width: 390, height: 844 }]) {
		await page.setViewportSize(viewport);
		await expect(pagePaging).toBeVisible();
		if (viewport.width < 480) {
			await optionsToggle.click();
			await results.locator('input[name="result-wrap-values"]').setChecked(false);
			await optionsToggle.click();
		}
		const tableWrap = results.locator('.query-result-table-wrap');
		const before = await tableWrap.evaluate(element => {
			const navigation = element.ownerDocument.querySelector('nav[aria-label="Query result paging"]');
			const navigationBounds = navigation.getBoundingClientRect();
			const bounds = element.getBoundingClientRect();
			return {
				wrapTop: bounds.top,
				navigationTop: navigationBounds.top,
				navigationBottom: navigationBounds.bottom,
				clientHeight: element.clientHeight,
				scrollHeight: element.scrollHeight
			};
		});
		expect(before.scrollHeight, `table must scroll vertically at ${viewport.width}px`).toBeGreaterThan(before.clientHeight);
		await tableWrap.evaluate(element => {
			element.scrollTop = Math.min(160, element.scrollHeight);
		});
		await expect.poll(() => tableWrap.evaluate(element => element.scrollTop),
			{ message: `table scrolls vertically at ${viewport.width}px` }).toBeGreaterThan(0);
		const after = await tableWrap.evaluate(element => {
			const document = element.ownerDocument;
			const navigation = document.querySelector('nav[aria-label="Query result paging"]');
			const navigationBounds = navigation.getBoundingClientRect();
			const bounds = element.getBoundingClientRect();
			const header = element.querySelector('thead th');
			const bodyRow = Array.from(element.querySelectorAll('tbody tr'))
				.find(row => row.cells.length === element.querySelectorAll('thead th').length);
			const headerBounds = header.getBoundingClientRect();
			const headerStyle = getComputedStyle(header);
			return {
				wrapTop: bounds.top,
				headerTop: headerBounds.top,
				headerBackground: headerStyle.backgroundColor,
				headerZIndex: headerStyle.zIndex,
				navigationTop: navigationBounds.top,
				navigationBottom: navigationBounds.bottom,
				scrollTop: element.scrollTop,
				scrollWidth: element.scrollWidth,
				clientWidth: element.clientWidth,
				headerCellLeft: headerBounds.left,
				bodyCellLeft: bodyRow ? bodyRow.cells[0].getBoundingClientRect().left : null
			};
		});
		console.log(`QUERY_RESULT_STICKY_HEADER ${JSON.stringify({ viewport, before, after })}`);
		await results.scrollIntoViewIfNeeded();
		await page.screenshot({ path: `${screenshotPrefix}-${viewport.width}px.png`, fullPage: false });
		expect(Math.abs(after.headerTop - after.wrapTop),
			`table column header stays at the scroller top at ${viewport.width}px`)
			.toBeLessThanOrEqual(1);
		expect(after.headerBackground, `table column header remains opaque at ${viewport.width}px`)
			.not.toBe('rgba(0, 0, 0, 0)');
		expect(Number(after.headerZIndex), `table column header stacks above body rows at ${viewport.width}px`)
			.toBeGreaterThan(0);
		expect(after.headerTop, `sticky column header stays below the page controls at ${viewport.width}px`)
			.toBeGreaterThanOrEqual(after.navigationBottom - 1);
		expect(after.navigationTop, `page controls remain visible at ${viewport.width}px`)
			.toBeGreaterThanOrEqual(0);
		expect(after.navigationBottom, `page controls remain in the viewport at ${viewport.width}px`)
			.toBeLessThanOrEqual(viewport.height);
		expect(after.navigationTop, `page controls remain in place while table rows scroll at ${viewport.width}px`)
			.toBeCloseTo(before.navigationTop, 1);
		if (viewport.width < 480) {
			await tableWrap.evaluate(element => {
				element.scrollLeft = 120;
			});
			const horizontal = await tableWrap.evaluate(element => {
				const headerCell = element.querySelector('thead th');
				const headerCount = element.querySelectorAll('thead th').length;
				const bodyRow = Array.from(element.querySelectorAll('tbody tr'))
					.find(row => row.cells.length === headerCount);
				return {
					scrollLeft: element.scrollLeft,
					scrollWidth: element.scrollWidth,
					clientWidth: element.clientWidth,
					headerCellLeft: headerCell.getBoundingClientRect().left,
					bodyCellLeft: bodyRow ? bodyRow.cells[0].getBoundingClientRect().left : null
				};
			});
			console.log(`QUERY_RESULT_STICKY_HEADER_HORIZONTAL ${JSON.stringify(horizontal)}`);
			expect(horizontal.scrollWidth).toBeGreaterThan(horizontal.clientWidth);
			expect(horizontal.scrollLeft).toBeGreaterThan(0);
			expect(Math.abs(horizontal.headerCellLeft - horizontal.bodyCellLeft))
				.toBeLessThanOrEqual(1);
		}
	}
	expect(pageErrors).toEqual([]);
});

test('compare mode collapses and restores navigation without reserving an empty sidebar', async ({ page }) => {
	await page.setViewportSize({ width: 1440, height: 1000 });
	await openPage(page, `repositories/${REPOSITORY_ID}/query`);
	await page.locator('#explain-trigger').click();
	await page.waitForFunction(() => {
		const explanation = document.querySelector('#query-explanation');
		const text = explanation && explanation.textContent.trim();
		return text && text !== 'Loading explanation...';
	});
	await page.locator('#compare-toggle').click();
	await expect(page.locator('body')).toHaveClass(/query-compare-mode/);
	await expect.poll(() => page.locator('#navigation').evaluate(element => getComputedStyle(element).visibility))
		.toBe('hidden');
	const closed = await compareGeometry(page);
	console.log(`COMPARE_NAV_CLOSED ${JSON.stringify(closed)}`);
	expect(closed.mainLeft).toBeLessThan(80);
	expect(closed.documentOverflow).toBeLessThanOrEqual(0);
	const sidebarToggle = page.locator('#query-sidebar-toggle');
	await sidebarToggle.focus();
	await page.keyboard.press('Tab');
	await page.keyboard.press('Shift+Tab');
	const closedToggle = await sidebarToggle.evaluate(button => {
		const box = button.getBoundingClientRect();
		const style = getComputedStyle(button);
		const action = button.closest('.workbench-action');
		const compare = document.querySelector('#query-compare-layout').getBoundingClientRect();
		const toolbar = document.querySelector('#query-compare-toolbar');
		const copyBox = document.querySelector('#query-compare-copy').getBoundingClientRect();
		const header = document.querySelector('#workbench-contextbar').getBoundingClientRect();
		return {
			width: box.width,
			height: box.height,
			left: box.left,
			right: box.right,
			toolbarContainsToggle: toolbar.contains(button),
			togglePrecedesCopy: box.right <= copyBox.left,
			centerOffset: Math.abs((box.top + box.bottom) / 2 - (copyBox.top + copyBox.bottom) / 2),
			headerOverlap: box.top < header.bottom && box.bottom > header.top
				&& box.left < header.right && box.right > header.left,
			focusVisible: button.matches(':focus-visible'),
			buttonOutlineWidth: parseFloat(style.outlineWidth),
			actionOutlineWidth: parseFloat(getComputedStyle(action).outlineWidth),
			compareTop: compare.top,
			compareBottom: compare.bottom,
			overlapsCompare: box.left < compare.right && box.right > compare.left
				&& box.top < compare.bottom && box.bottom > compare.top
		};
	});
	console.log(`COMPARE_SIDEBAR_TOGGLE_CLOSED ${JSON.stringify(closedToggle)}`);
	expect(closedToggle.width).toBeGreaterThanOrEqual(36);
	expect(closedToggle.height).toBeGreaterThanOrEqual(36);
	expect(closedToggle.toolbarContainsToggle).toBe(true);
	expect(closedToggle.togglePrecedesCopy).toBe(true);
	expect(closedToggle.centerOffset).toBeLessThanOrEqual(2);
	expect(closedToggle.headerOverlap).toBe(false);
	expect(closedToggle.focusVisible).toBe(true);
	expect(Math.max(closedToggle.buttonOutlineWidth, closedToggle.actionOutlineWidth)).toBeGreaterThanOrEqual(2);
	expect(closedToggle.overlapsCompare).toBe(false);

	const queryFormLeftBeforeOpen = await page.locator('.query-form')
		.evaluate(element => element.getBoundingClientRect().left);
	await sidebarToggle.click();
	await expect(page.locator('body')).toHaveClass(/query-compare-nav-open/);
	await expect.poll(() => page.locator('#navigation').evaluate(element => getComputedStyle(element).visibility))
		.toBe('visible');
	try {
		await expect.poll(async () => {
			const geometry = await compareMenuGeometry(page);
			return Math.max(Math.abs(geometry.menuLeft - geometry.toggleLeft),
				Math.abs(geometry.menuTop - geometry.toggleBottom - 8));
		}).toBeLessThanOrEqual(2);
	} catch (error) {
		console.log(`COMPARE_NAV_ANCHOR_SETTLED_DIAGNOSTIC ${JSON.stringify(await compareMenuGeometry(page))}`);
		throw error;
	}
	const openMenuGeometry = await compareMenuGeometry(page);
	console.log(`COMPARE_NAV_ANCHOR ${JSON.stringify(openMenuGeometry)}`);
	expect(Math.abs(openMenuGeometry.menuLeft - openMenuGeometry.toggleLeft)).toBeLessThanOrEqual(2);
	expect(openMenuGeometry.menuTop).toBeGreaterThanOrEqual(openMenuGeometry.toggleBottom + 7);
	expect(openMenuGeometry.menuTop).toBeLessThanOrEqual(openMenuGeometry.toggleBottom + 10);
	expect(Math.abs(openMenuGeometry.queryFormLeft - queryFormLeftBeforeOpen)).toBeLessThanOrEqual(1);
	expect(openMenuGeometry.documentOverflow).toBeLessThanOrEqual(0);
	const opened = await compareGeometry(page);
	console.log(`COMPARE_NAV_OPEN ${JSON.stringify(opened)}`);
	expect(opened.navigationLinks).toBeGreaterThan(0);
	expect(opened.documentOverflow).toBeLessThanOrEqual(0);

	await page.setViewportSize({ width: 1024, height: 760 });
	try {
		await expect.poll(async () => {
			const geometry = await compareMenuGeometry(page);
			return Math.max(Math.abs(geometry.menuLeft - geometry.toggleLeft),
				Math.abs(geometry.menuTop - geometry.toggleBottom - 8));
		}).toBeLessThanOrEqual(2);
	} catch (error) {
		console.log(`COMPARE_NAV_ANCHOR_MOBILE_DIAGNOSTIC ${JSON.stringify(await compareMenuGeometry(page))}`);
		throw error;
	}
	await page.evaluate(() => window.scrollTo(0, 120));
	await expect.poll(() => page.evaluate(() => window.scrollY)).toBeGreaterThan(0);
	await expect.poll(async () => {
		const geometry = await compareMenuGeometry(page);
		return Math.max(Math.abs(geometry.menuLeft - geometry.toggleLeft),
			Math.abs(geometry.menuTop - geometry.toggleBottom - 8));
	}).toBeLessThanOrEqual(2);

	await page.locator('#query-sidebar-toggle').click();
	await expect(page.locator('body')).not.toHaveClass(/query-compare-nav-open/);
	await expect.poll(() => page.locator('#navigation').evaluate(element => getComputedStyle(element).visibility))
		.toBe('hidden');
	await expect(page.locator('#query-compare-close')).toBeVisible();
	await page.locator('#query-compare-close').click();
	await expect(page.locator('body')).not.toHaveClass(/query-compare-mode/);
	const restored = await compareGeometry(page);
	console.log(`COMPARE_NAV_RESTORED ${JSON.stringify(restored)}`);
	expect(restored.navigationLinks).toBeGreaterThan(0);
	expect(restored.documentOverflow).toBeLessThanOrEqual(0);
	const restoredNavigationLink = page.locator('#navigation a:visible:not([aria-current="page"])').first();
	await expect(restoredNavigationLink).toBeVisible();
	const restoredNavigationPath = await restoredNavigationLink.evaluate(link => new URL(link.href).pathname);
	await restoredNavigationLink.click();
	await expect.poll(() => new URL(page.url()).pathname).toBe(restoredNavigationPath);
});

test('dark compare keeps a collapsed navigation disclosure out of both panes', async ({ page }) => {
	for (const width of [1440, 390]) {
		await page.setViewportSize({ width, height: 1000 });
		await openPage(page, `repositories/${REPOSITORY_ID}/query`);
		await page.evaluate(() => window.RDF4JWorkbenchTheme.setPreference('dark'));
		await page.locator('.CodeMirror').first().evaluate((editor, query) => editor.CodeMirror.setValue(query),
			'SELECT ?s WHERE { ?s ?p ?o }');
		await enterCompareMode(page);
		await waitForCompareTransition(page);
		await page.evaluate(() => window.scrollTo(0, 0));

		const coverage = await page.evaluate(() => {
			const disclosure = document.querySelector('#workbench-navigation-disclosure');
			const navigation = document.querySelector('#navigation');
			const toggle = document.querySelector('#query-sidebar-toggle');
			const editor = document.querySelector('.query-compare-pane .CodeMirror');
			const editorBounds = editor.getBoundingClientRect();
			const probeX = Math.min(window.innerWidth - 1, editorBounds.left + 8);
			const probeY = Math.min(window.innerHeight - 1, editorBounds.top + 8);
			const hit = document.elementFromPoint(probeX, probeY);
			const hitNavigation = hit && (hit.closest('#navigation') || hit.closest('#workbench-navigation-disclosure'));
			const navigationStyle = getComputedStyle(navigation);
			const disclosureStyle = getComputedStyle(disclosure);
			const disclosureBounds = disclosure.getBoundingClientRect();
			return {
				width: window.innerWidth,
				editorBounds: { top: editorBounds.top, bottom: editorBounds.bottom, height: editorBounds.height },
				editorVisibleInViewport: editorBounds.top >= 0 && editorBounds.bottom <= window.innerHeight,
				darkTheme: document.documentElement.getAttribute('data-theme') === 'dark',
				compareMode: document.body.classList.contains('query-compare-mode'),
				compareMenuOpen: document.body.classList.contains('query-compare-nav-open'),
				menuExpanded: toggle.getAttribute('aria-expanded'),
				disclosureOpen: disclosure.open,
				disclosureBounds: { left: disclosureBounds.left, top: disclosureBounds.top,
					width: disclosureBounds.width, height: disclosureBounds.height },
				disclosureBackground: disclosureStyle.backgroundColor,
				disclosurePointerEvents: disclosureStyle.pointerEvents,
				navigationVisibility: navigationStyle.visibility,
				navigationOpacity: navigationStyle.opacity,
				hitTarget: hit && `${hit.tagName.toLowerCase()}#${hit.id}.${String(hit.className || '').replace(/\s+/g, '.')}`,
				hitNavigation: Boolean(hitNavigation),
				probe: { x: probeX, y: probeY }
			};
		});
		console.log(`DARK_COMPARE_NAVIGATION ${JSON.stringify(coverage)}`);
		if (VISUAL_ARTIFACT_DIRECTORY) {
			const directory = path.join(VISUAL_ARTIFACT_DIRECTORY, 'final', 'dark-expanded');
			fs.mkdirSync(directory, { recursive: true });
			await page.screenshot({ path: path.join(directory,
				`query-compare-navigation-closed-${width}-dark.png`), fullPage: true });
		}
		expect(coverage.darkTheme).toBe(true);
		expect(coverage.editorVisibleInViewport).toBe(true);
		expect(coverage.compareMode).toBe(true);
		expect(coverage.compareMenuOpen).toBe(false);
		expect(coverage.menuExpanded).toBe('false');
		expect(coverage.navigationVisibility).toBe('hidden');
		expect(coverage.disclosureBackground).toBe('rgba(0, 0, 0, 0)');
		expect(coverage.disclosurePointerEvents).toBe('none');
		expect(coverage.hitNavigation).toBe(false);
		await expect(page.locator('#query-diff-trigger')).toBeEnabled();
		await page.locator('#query-diff-trigger').click();
		await expect(page.locator('#query-diff-modal')).toHaveClass(/query-diff-modal--open/);
		await page.evaluate(async () => {
			const modal = document.querySelector('#query-diff-modal');
			const targets = [modal, ...Array.from(modal.querySelectorAll('*'))];
			const animations = targets.flatMap(element => element.getAnimations());
			await Promise.all(animations.map(animation => animation.finished.catch(() => undefined)));
		});
		if (VISUAL_ARTIFACT_DIRECTORY) {
			const directory = path.join(VISUAL_ARTIFACT_DIRECTORY, 'final', 'dark-expanded');
			fs.mkdirSync(directory, { recursive: true });
			await page.screenshot({ path: path.join(directory,
				`query-compare-diff-open-${width}-dark.png`), fullPage: true });
		}
	}
});

test('compare menu remains a touch-sized toolbar action and anchors its navigation on mobile', async ({ page }) => {
	await page.setViewportSize({ width: 390, height: 900 });
	await openPage(page, `repositories/${REPOSITORY_ID}/query`);
	const navigationDisclosure = page.locator('#workbench-navigation-disclosure');
	const navigationSummary = page.locator('#workbench-navigation-summary');
	if (await navigationDisclosure.evaluate(element => element.open)) {
		await navigationSummary.click();
	}
	await expect.poll(() => navigationDisclosure.evaluate(element => element.open)).toBe(false);
	await page.locator('#explain-trigger').click();
	await page.waitForFunction(() => {
		const explanation = document.querySelector('#query-explanation');
		const text = explanation && explanation.textContent.trim();
		return text && text !== 'Loading explanation...';
	});
	await page.locator('#compare-toggle').click();
	const toggle = page.locator('#query-sidebar-toggle');
	await expect(toggle).toBeVisible();
	const touchTargets390 = await compareActionTargets(page);
	console.log(`COMPARE_ACTION_TOUCH_TARGETS_390 ${JSON.stringify(touchTargets390)}`);
	expect(touchTargets390.every(action => action.visible && action.targetHeight >= 44)).toBe(true);
	expect(touchTargets390.every(action => action.wrapperHeight >= 44)).toBe(true);
	expect(Math.max(...touchTargets390.map(action => action.wrapperHeight))
		- Math.min(...touchTargets390.map(action => action.wrapperHeight))).toBeLessThanOrEqual(1);
	await toggle.focus();
	const closed = await toggle.evaluate(button => {
		const box = button.getBoundingClientRect();
		const toolbar = document.querySelector('#query-compare-toolbar');
		const copy = document.querySelector('#query-compare-copy').getBoundingClientRect();
		const header = document.querySelector('#workbench-contextbar').getBoundingClientRect();
		return {
			width: box.width,
			height: box.height,
			activeElementId: document.activeElement && document.activeElement.id,
			toolbarContainsToggle: toolbar.contains(button),
			togglePrecedesCopy: box.right <= copy.left,
			centerOffset: Math.abs((box.top + box.bottom) / 2 - (copy.top + copy.bottom) / 2),
			focusVisible: button.matches(':focus-visible'),
			buttonOutlineWidth: parseFloat(getComputedStyle(button).outlineWidth),
			actionOutlineWidth: parseFloat(getComputedStyle(button.closest('.workbench-action')).outlineWidth),
			headerOverlap: box.top < header.bottom && box.bottom > header.top
				&& box.left < header.right && box.right > header.left
		};
	});
	console.log(`COMPARE_SIDEBAR_TOGGLE_MOBILE ${JSON.stringify(closed)}`);
	expect(closed.width).toBeGreaterThanOrEqual(44);
	expect(closed.height).toBeGreaterThanOrEqual(44);
	expect(closed.activeElementId).toBe('query-sidebar-toggle');
	expect(closed.toolbarContainsToggle).toBe(true);
	expect(closed.togglePrecedesCopy).toBe(true);
	expect(closed.centerOffset).toBeLessThanOrEqual(2);
	expect(Math.max(closed.buttonOutlineWidth, closed.actionOutlineWidth)).toBeGreaterThanOrEqual(2);
	expect(closed.headerOverlap).toBe(false);

	await toggle.click();
	await expect(page.locator('body')).toHaveClass(/query-compare-nav-open/);
	await expect.poll(() => page.locator('#navigation').evaluate(element => getComputedStyle(element).visibility))
		.toBe('visible');
	try {
		await expect.poll(async () => {
			const geometry = await compareMenuGeometry(page);
			return Math.max(Math.abs(geometry.menuLeft - geometry.toggleLeft),
				Math.abs(geometry.menuTop - geometry.toggleBottom - 8));
		}).toBeLessThanOrEqual(2);
	} catch (error) {
		console.log(`COMPARE_NAV_ANCHOR_MOBILE_DIAGNOSTIC ${JSON.stringify(await compareMenuGeometry(page))}`);
		throw error;
	}
	const opened = await page.evaluate(() => {
		const toggleBox = document.querySelector('#query-sidebar-toggle').getBoundingClientRect();
		const menuBox = document.querySelector('#navigation').getBoundingClientRect();
		return {
			menuLeft: menuBox.left,
			toggleLeft: toggleBox.left,
			menuTop: menuBox.top,
			toggleBottom: toggleBox.bottom
		};
	});
	console.log(`COMPARE_NAV_ANCHOR_MOBILE ${JSON.stringify(opened)}`);
	expect(Math.abs(opened.menuLeft - opened.toggleLeft)).toBeLessThanOrEqual(2);
	expect(opened.menuTop).toBeGreaterThanOrEqual(opened.toggleBottom + 7);
	expect(opened.menuTop).toBeLessThanOrEqual(opened.toggleBottom + 10);
	expect(await page.evaluate(() => document.documentElement.scrollWidth - document.documentElement.clientWidth))
		.toBeLessThanOrEqual(0);
	await page.setViewportSize({ width: 320, height: 700 });
	const touchTargets320 = await compareActionTargets(page);
	console.log(`COMPARE_ACTION_TOUCH_TARGETS_320 ${JSON.stringify(touchTargets320)}`);
	expect(touchTargets320.every(action => action.visible && action.targetHeight >= 44)).toBe(true);
	expect(touchTargets320.every(action => action.wrapperHeight >= 44)).toBe(true);
	expect(Math.max(...touchTargets320.map(action => action.wrapperHeight))
		- Math.min(...touchTargets320.map(action => action.wrapperHeight))).toBeLessThanOrEqual(1);
	await expect.poll(async () => {
		const geometry = await compareMenuGeometry(page);
		return Math.max(Math.abs(geometry.menuLeft - geometry.toggleLeft),
			Math.abs(geometry.menuTop - geometry.toggleBottom - 8));
	}).toBeLessThanOrEqual(2);
	const narrow = await compareMenuGeometry(page);
	expect(narrow.menuLeft).toBeGreaterThanOrEqual(0);
	expect(narrow.menuRight).toBeLessThanOrEqual(narrow.viewportWidth - 8);
	expect(narrow.documentOverflow).toBeLessThanOrEqual(0);
	await page.evaluate(() => window.scrollTo(0, 120));
	await expect.poll(() => page.evaluate(() => window.scrollY)).toBeGreaterThan(0);
	await expect.poll(async () => {
		const geometry = await compareMenuGeometry(page);
		return Math.max(Math.abs(geometry.menuLeft - geometry.toggleLeft),
			Math.abs(geometry.menuTop - geometry.toggleBottom - 8));
	}).toBeLessThanOrEqual(2);
	await expect.poll(() => navigationDisclosure.evaluate(element => element.open)).toBe(true);
	const summaryLink = page.getByRole('link', { name: 'Summary', exact: true });
	await expect(summaryLink).toBeVisible();
	await summaryLink.click();
	await expect(page).toHaveURL(/\/summary$/);
	await expect.poll(() => navigationDisclosure.evaluate(element => element.open)).toBe(false);
	await navigationSummary.click();
	await expect.poll(() => navigationDisclosure.evaluate(element => element.open)).toBe(true);
	const queryLink = page.getByRole('link', { name: 'Query', exact: true });
	await expect(queryLink).toBeVisible();
	await queryLink.click();
	await expect(page).toHaveURL(new RegExp(`/repositories/${REPOSITORY_ID}/query$`));
});

test('compare navigation follows the responsive menu state after crossing its breakpoint', async ({ page }) => {
	const navigationDisclosure = page.locator('#workbench-navigation-disclosure');
	const navigationSummary = page.locator('#workbench-navigation-summary');

	await page.setViewportSize({ width: 390, height: 900 });
	await openPage(page, `repositories/${REPOSITORY_ID}/query`);
	if (await navigationDisclosure.evaluate(element => element.open)) {
		await navigationSummary.click();
	}
	await expect.poll(() => navigationDisclosure.evaluate(element => element.open)).toBe(false);
	await enterCompareMode(page);
	await page.setViewportSize({ width: 1440, height: 1000 });
	await page.locator('#query-compare-close').click();
	await expect(page.locator('body')).not.toHaveClass(/query-compare-mode/);
	await expect(page.locator('#query-compare-layout')).not.toHaveClass(/query-compare-layout--closing/);
	await expect.poll(() => navigationDisclosure.evaluate(element => element.open)).toBe(true);
	const desktopNavigationLink = page.getByRole('link', { name: 'Summary', exact: true });
	await expect(desktopNavigationLink).toBeVisible();
	await captureResponsiveCompareState(page, 'compare-restored-desktop-after-resize-1440.png');
	await desktopNavigationLink.click();
	await expect(page).toHaveURL(/\/summary$/);

	await page.setViewportSize({ width: 1440, height: 1000 });
	await openPage(page, `repositories/${REPOSITORY_ID}/query`);
	await expect.poll(() => navigationDisclosure.evaluate(element => element.open)).toBe(true);
	await enterCompareMode(page);
	await page.setViewportSize({ width: 390, height: 900 });
	await page.locator('#query-compare-close').click();
	await expect(page.locator('body')).not.toHaveClass(/query-compare-mode/);
	await expect(page.locator('#query-compare-layout')).not.toHaveClass(/query-compare-layout--closing/);
	await expect.poll(() => navigationDisclosure.evaluate(element => element.open)).toBe(false);
	await expect(navigationSummary).toBeVisible();
	await captureResponsiveCompareState(page, 'compare-restored-mobile-after-resize-390.png');
	await navigationSummary.click();
	await expect.poll(() => navigationDisclosure.evaluate(element => element.open)).toBe(true);
	const mobileNavigationLink = page.getByRole('link', { name: 'Summary', exact: true });
	await expect(mobileNavigationLink).toBeVisible();
	await mobileNavigationLink.click();
	await expect(page).toHaveURL(/\/summary$/);
});

test('coarse-pointer compare actions remain touch-sized at tablet widths', async ({ browser }) => {
	const context = await browser.newContext({
		viewport: { width: 1024, height: 900 },
		isMobile: true,
		hasTouch: true
	});
	const page = await context.newPage();
	try {
		await openPage(page, `repositories/${REPOSITORY_ID}/query`);
		const coarsePointer = await page.evaluate(() => matchMedia('(pointer: coarse)').matches);
		console.log(`COARSE_POINTER_MEDIA_MATCHES ${coarsePointer}`);
		expect(coarsePointer).toBe(true);
		await enterCompareMode(page);

		const actions = await compareActionTargets(page);
		console.log(`COARSE_POINTER_COMPARE_ACTIONS ${JSON.stringify(actions)}`);
		expect(actions.length).toBe(4);
		expect(actions.every(action => action.visible)).toBe(true);
		expect(actions.every(action => action.targetHeight >= 44)).toBe(true);
		expect(actions.every(action => action.wrapperHeight >= 44)).toBe(true);
		expect(Math.max(...actions.map(action => action.wrapperHeight))
			- Math.min(...actions.map(action => action.wrapperHeight))).toBeLessThanOrEqual(1);
		await waitForCompareTransition(page);
		const viewport = await page.evaluate(() => ({
			innerWidth: window.innerWidth,
			clientWidth: document.documentElement.clientWidth,
			scrollWidth: document.documentElement.scrollWidth,
			visualViewportWidth: window.visualViewport?.width,
			devicePixelRatio: window.devicePixelRatio,
			compareLayoutWidth: document.querySelector('#query-compare-layout').getBoundingClientRect().width,
			coarsePointer: matchMedia('(pointer: coarse)').matches
		}));
		console.log(`COARSE_POINTER_COMPARE_VIEWPORT ${JSON.stringify(viewport)}`);
		await captureResponsiveCompareState(page, 'compare-actions-coarse-pointer-1024.png', { fullPage: false });
		expect(viewport.scrollWidth).toBeLessThanOrEqual(viewport.clientWidth);
	} finally {
		await context.close();
	}
});

async function enterCompareMode(page) {
	await page.locator('#explain-trigger').click();
	await page.waitForFunction(() => {
		const explanation = document.querySelector('#query-explanation');
		const text = explanation && explanation.textContent.trim();
		return text && text !== 'Loading explanation...';
	});
	await page.locator('#compare-toggle').click();
	await expect(page.locator('body')).toHaveClass(/query-compare-mode/);
}

async function waitForCompareTransition(page) {
	await page.evaluate(async () => {
		const selectors = ['#query-compare-layout', '#content', '#title_heading', '.query-form', '#navigation',
			'.workbench-navigation-disclosure'];
		const animations = selectors.flatMap(selector => {
			const element = document.querySelector(selector);
			return element ? element.getAnimations() : [];
		});
		await Promise.all(animations.map(animation => animation.finished.catch(() => undefined)));
	});
}

async function compareActionTargets(page) {
	return page.locator('#query-sidebar-toggle, #query-compare-copy, #query-compare-swap, #query-compare-close')
		.evaluateAll(elements => elements.map(element => {
			const targetBounds = element.getBoundingClientRect();
			const wrapper = element.closest('.workbench-action') || element;
			const wrapperBounds = wrapper.getBoundingClientRect();
			return {
				id: element.id,
				visible: targetBounds.width > 0 && targetBounds.height > 0
					&& getComputedStyle(element).visibility === 'visible',
				targetHeight: targetBounds.height,
				wrapperHeight: wrapperBounds.height
			};
		}));
}

async function captureResponsiveCompareState(page, filename, { fullPage = true } = {}) {
	if (!VISUAL_ARTIFACT_DIRECTORY) {
		return;
	}
	const directory = path.join(VISUAL_ARTIFACT_DIRECTORY, 'final', 'states');
	fs.mkdirSync(directory, { recursive: true });
	await page.screenshot({ path: path.join(directory, filename), fullPage });
}

test('advanced creation forms separate their contents and provide labeled choice hit areas', async ({ page }) => {
	await page.setViewportSize({ width: 390, height: 900 });
	const violations = [];
	for (const type of CREATION_TYPES) {
		await openPage(page, `repositories/NONE/create?type=${type}`);
		const details = page.locator('.workbench-advanced[data-workbench-detail-disclosure="true"]');
		if (await details.count()) {
			const toggle = details.locator(':scope > .workbench-disclosure__toggle');
			await toggle.press('Enter');
			const state = await details.evaluate(element => {
				const toggleElement = element.querySelector(':scope > .workbench-disclosure__toggle');
				const panel = element.querySelector(':scope > .workbench-disclosure__panel');
				const advancedFields = panel && panel.querySelector('.workbench-advanced-fields');
				const firstField = advancedFields && advancedFields.querySelector('.workbench-advanced__field');
				const label = firstField && firstField.querySelector(':scope > label, :scope > span');
				const control = firstField && firstField.querySelector('.workbench-advanced__control');
				const radios = Array.from(element.querySelectorAll('input[type="radio"]'));
				const toggleStyle = getComputedStyle(toggleElement);
				const toggleBox = toggleElement.getBoundingClientRect();
				const fieldBox = firstField && firstField.getBoundingClientRect();
				const labelBox = label && label.getBoundingClientRect();
				const controlBox = control && control.getBoundingClientRect();
				return {
					toggleBottom: toggleBox.bottom,
					firstFieldTop: fieldBox ? fieldBox.top : 0,
					contentGap: fieldBox ? fieldBox.top - toggleBox.bottom : 0,
					labelBottom: labelBox ? labelBox.bottom : 0,
					controlTop: controlBox ? controlBox.top : 0,
					focusVisible: toggleElement.matches(':focus-visible'),
					focusOutlineWidth: toggleStyle.outlineWidth,
					toggleRadius: toggleStyle.borderRadius,
					radioLabels: radios.map(input => ({ value: input.value, count: input.labels.length }))
				};
			});
			if (state.contentGap < 8 || state.toggleRadius === '0px'
					|| state.labelBottom > state.controlTop + 1
					|| state.radioLabels.some(choice => choice.count !== 1)) {
				violations.push({ type, ...state });
			}
			if (type === 'memory-customrule') {
				console.log(`ADVANCED_CHOICE_GEOMETRY ${JSON.stringify({ type, ...state })}`);
				expect(state.contentGap).toBeGreaterThanOrEqual(8);
				expect(state.toggleRadius).not.toBe('0px');
				expect(state.labelBottom).toBeLessThanOrEqual(state.controlTop + 1);
				expect(state.radioLabels.length).toBeGreaterThan(0);
				expect(state.radioLabels.every(choice => choice.count === 1)).toBe(true);
				expect(state.focusVisible).toBe(true);
				expect(parseFloat(state.focusOutlineWidth)).toBeGreaterThanOrEqual(2);
			}
		}
		if (type === 'federate') {
			const checkboxLabels = await page.locator('input.memberID').evaluateAll(inputs =>
				inputs.map(input => ({ value: input.value, count: input.labels.length })));
				if (checkboxLabels.some(choice => choice.count !== 1)) {
				violations.push({ type, checkboxLabels });
			}
		}
	}
	console.log(`ADVANCED_FORM_LAYOUT_VIOLATIONS ${JSON.stringify(violations)}`);
	expect(violations).toEqual([]);
});

async function openPage(page, route) {
	await page.goto(`${WORKBENCH_BASE_URL}/${route}`, { waitUntil: 'load' });
	await page.locator('#workbench-page-surface').waitFor({ state: 'visible', timeout: 15_000 });
	await page.evaluate(() => document.fonts.ready);
}

async function selectViolations(scope) {
	return scope.locator('select').evaluateAll(selects => selects.map(select => {
		const wrapper = select.parentElement;
		const chevron = wrapper && wrapper.querySelector('.workbench-select-chevron');
		const style = getComputedStyle(select);
		return {
			id: select.id || select.name,
			wrapped: Boolean(wrapper && wrapper.classList.contains('workbench-select-control')),
			appearance: style.appearance,
			paddingRight: parseFloat(style.paddingRight),
			chevronCount: chevron ? 1 : 0,
			chevronInside: Boolean(chevron && wrapper.contains(chevron)),
			chevronWidth: chevron ? parseFloat(getComputedStyle(chevron).width) : 0,
			chevronRenderedWidth: chevron ? chevron.getBoundingClientRect().width : 0,
			wrapperWidth: wrapper ? wrapper.getBoundingClientRect().width : 0,
			selectWidth: select.getBoundingClientRect().width,
			chevronLeft: chevron ? chevron.getBoundingClientRect().left : 0,
			chevronRight: chevron ? chevron.getBoundingClientRect().right : 0,
			selectLeft: select.getBoundingClientRect().left,
			selectRight: select.getBoundingClientRect().right,
			arrowInsideSelectBoundary: Boolean(chevron && chevron.getBoundingClientRect().left >= select.getBoundingClientRect().left - 0.5
				&& chevron.getBoundingClientRect().right <= select.getBoundingClientRect().right + 0.5
				&& chevron.getBoundingClientRect().top >= select.getBoundingClientRect().top - 0.5
				&& chevron.getBoundingClientRect().bottom <= select.getBoundingClientRect().bottom + 0.5)
		};
	})).then(selects => selects.filter(select => !select.wrapped || select.appearance !== 'none'
		|| select.paddingRight < 32 || select.chevronCount !== 1 || !select.chevronInside || select.chevronWidth !== 16
		|| !select.arrowInsideSelectBoundary));
}

async function disclosureResultGap(frame, panelSelector, resultLayout) {
	return frame.locator('#query-result-layout').evaluate((layout, args) => {
		const panel = document.querySelector(args.panelSelector);
		const firstResult = args.resultLayout === 'records'
			? document.querySelector('#query-result-records .query-result-record')
			: document.querySelector('#query-result-table-wrap table.data');
		return firstResult.getBoundingClientRect().top - panel.getBoundingClientRect().bottom;
	}, { panelSelector, resultLayout });
}

async function compareGeometry(page) {
	return page.evaluate(() => ({
		mainLeft: document.querySelector('#content').getBoundingClientRect().left,
		navigationLinks: document.querySelectorAll('#navigation a').length,
		documentOverflow: document.documentElement.scrollWidth - document.documentElement.clientWidth
	}));
}

async function compareMenuGeometry(page) {
	return page.evaluate(() => {
		const toggle = document.querySelector('#query-sidebar-toggle').getBoundingClientRect();
		const navigation = document.querySelector('#navigation');
		const menu = navigation.getBoundingClientRect();
		const menuStyle = getComputedStyle(navigation);
		return {
			menuLeft: menu.left,
			menuRight: menu.right,
			toggleLeft: toggle.left,
			menuTop: menu.top,
			toggleBottom: toggle.bottom,
			queryFormLeft: document.querySelector('.query-form').getBoundingClientRect().left,
			documentOverflow: document.documentElement.scrollWidth - document.documentElement.clientWidth,
			menuPosition: menuStyle.position,
			menuDisplay: menuStyle.display,
			menuTransform: menuStyle.transform,
			menuTopStyle: menuStyle.top,
			menuLeftStyle: menuStyle.left,
			viewportWidth: document.documentElement.clientWidth,
			bodyMenuLeft: document.body.style.getPropertyValue('--query-compare-nav-left'),
			bodyMenuTop: document.body.style.getPropertyValue('--query-compare-nav-top'),
			scrollY: window.scrollY,
			ancestors: Array.from((function* () {
				for (var element = navigation.parentElement; element; element = element.parentElement) {
					yield element;
				}
			})()).map(element => {
				const style = getComputedStyle(element);
				const rect = element.getBoundingClientRect();
				return { tag: element.tagName, id: element.id, className: element.className,
					position: style.position, transform: style.transform, contain: style.contain,
					top: rect.top, left: rect.left };
			})
		};
	});
}

function repositoryConfiguration(repositoryId) {
	return `@prefix rdfs: <http://www.w3.org/2000/01/rdf-schema#>.
@prefix config: <tag:rdf4j.org,2023:config/>.
[] a config:Repository ; config:rep.id "${repositoryId}" ; rdfs:label "Workbench visual follow-up fixture" ;
   config:rep.impl [ config:rep.type "openrdf:SailRepository" ;
      config:sail.impl [ config:sail.type "openrdf:MemoryStore" ] ].`;
}
